{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included randomised trials in people with suspected, probable, or confirmed covid-19 that compared blood products and covid-19-specific antiviral antibodies against one another or against no intervention, placebo, or standard care... No restrictions were applied based on severity of illness or setting.",
      "reason": "Eligible designs (randomised trials), population, interventions, comparators, and setting are all explicitly specified; exclusion of non-randomised trials and other intervention types is also stated."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language.",
      "reason": "Publication status and language restrictions are explicitly addressed (none applied), confirming report-characteristic eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_15",
      "quote": null,
      "reason": "The manuscript does not distinguish between excluding studies because outcomes were not measured versus outcomes not being reported; no such distinction appears in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "We included randomised trials... that compared blood products and covid-19-specific antiviral antibodies against one another or against no intervention, placebo, or standard care... We meta-analysed interventions with ≥100 patients randomised or ≥20 events per treatment arm.",
      "reason": "Intervention groups and comparisons are specified (text_15, text_6), and a synthesis grouping threshold is given (text_6, callout_0), but the full list of intervention nodes/groups used in each synthesis is not fully enumerated in the retrieved methods evidence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "limited meta-analysis of interventions that were randomised to at least 100 patients (or had ≥20 events) to avoid spurious or imprecise findings with network meta-analysis",
      "reason": "A rationale is provided for the notable restriction on synthesis eligibility (minimum sample/event thresholds), and text_15 also explains why certain trial types (vaccines, prophylaxis) were handled separately."
    }
  ],
  "confidence": 90
}

