{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Selected outcomes include mortality (closest to 90 days), mechanical ventilation (total number of patients, over 90 days), adverse events leading to discontinuation (within 28 days), viral clearance (closest to 7 days ±3 days), transfusion-related acute lung injury (TRALI; total number of patients, within 28 days), transfusion-associated circulatory overload (TACO; total number of patients, within 28 days), infusion reactions (total number of patients, within 28 days), duration of hospitalisation, intensive care unit (ICU) length of stay, time to symptom resolution or clinical improvement, and time to viral clearance.",
      "reason": "The outcomes of interest are comprehensively listed with definitions (e.g. TRALI, TACO) and rationale for some (viral clearance as surrogate for transmissibility)."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "mortality (closest to 90 days), mechanical ventilation (total number of patients, over 90 days), adverse events leading to discontinuation (within 28 days), viral clearance (closest to 7 days ±3 days)",
      "reason": "Time frames are specified for most outcomes; some outcomes (e.g. duration of hospitalisation, ICU length of stay) are inherently time-based measures without an additional time point needed."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "outcomes of interest (means or medians and measures of variability for continuous outcomes and the number of participants analysed and the number of participants who experienced an event for dichotomous outcomes)",
      "reason": "The types of results collected are described, but the manuscript does not explicitly state whether all results compatible with each outcome domain (all measures, time points, analyses) were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence indicates that only a subset of compatible results was selected; no selection process is described and no statement suggests it was needed."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_13",
      "quote": "A protocol provides the detailed methods of this systematic review, including all updates (see supplementary data on bmj.com).",
      "reason": "No changes to outcome domains are reported in the retrieved evidence; the living review updates are handled in the protocol/supplementary data, and no such changes are documented in the provided text."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of changes to result-selection processes within outcome domains is reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "the review team chose thresholds of small but important effects by consensus: 1% for mortality, 2% for mechanical ventilation, 1% for hospitalisation, 1 day for duration of hospitalisation, and 2% for all adverse effects",
      "reason": "Key outcomes for interpreting conclusions (mortality, mechanical ventilation, hospitalisation, adverse effects) are identified with rationale (consensus thresholds of minimal importance)."
    }
  ],
  "confidence": 82
}

