{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_18",
      "quote": "use a revision of the Cochrane tool for assessing risk of bias in randomised trials (RoB 2.0) 28 to rate trials",
      "reason": "The tool (RoB 2.0, a revision of the Cochrane risk of bias tool) is explicitly named, with reference 28 to Sterne et al."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_18",
      "quote": "across the following domains: bias arising from the randomisation process; bias owing to departures from the intended intervention; bias from missing outcome data; bias in measurement of the outcome; bias in selection of the reported results, including deviations from the registered protocol; bias due to competing risks; and bias arising from early termination for benefit",
      "reason": "All domains assessed by the tool are enumerated."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_18",
      "quote": "We rate trials at high risk of bias overall if one or more domains were rated as (c) someconcerns, probably high risk of bias or as (d) high risk of bias, and as low risk of bias overall if all domains were rated as ( b ) some concerns, probably low risk of bias or ( a ) low risk of bias.",
      "reason": "An overall risk-of-bias judgement is made and the derivation rules are explicitly reported."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "PRESENT",
      "chunk_id": "text_18",
      "quote": "use a revision of the Cochrane tool for assessing risk of bias in randomised trials (RoB 2.0)",
      "reason": "The use of a revision/modification of the Cochrane RoB 2.0 tool is described (also 'a modification of the Cochrane risk of bias 2.0 tool' in text_6), though detailed description of the adaptations is limited; the revision is identified and its modified domains and rules are given."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No newly developed risk-of-bias tool was used; an existing tool (RoB 2.0) was applied."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
      "chunk_id": "text_18",
      "quote": "reviewers, following training and calibration exercises, use a revision of the Cochrane tool ... Reviewers resolve discrepancies by discussion and, when necessary, with adjudication by a third party.",
      "reason": "Multiple reviewers ('pairs' implied by 'reviewers' and third-party adjudication) assess risk of bias, with discrepancy resolution by discussion and third-party adjudication described. Independence is implied by the discrepancy-resolution process but not explicitly stated as independent assessment."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of processes to obtain or confirm risk-of-bias information from study investigators; this conditional element does not appear to apply."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools for risk-of-bias assessment are reported; the assessment was performed manually by reviewers."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "We summarised the effect of interventions on dichotomous outcomes using odds ratios and their corresponding 95% credible interval (CI). For outcomes with extremely rare events, we summarised the effect of interventions using risk difference and 95% CI. For continuous outcomes, specifically duration of hospital stay, we used the mean difference and corresponding 95% CI... For time to symptom resolution, time to viral clearance, and duration of mechanical ventilation, we performed the analyses using ratio of means and corresponding 95% CI before calculating the mean difference in days",
      "reason": "The methods specify the effect measure for each outcome type: odds ratios for dichotomous outcomes, risk difference for extremely rare events, mean difference for duration of hospital stay, and ratio of means for time-to-event outcomes."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "the review team chose thresholds of small but important effects by consensus: 1% for mortality, 2% for mechanical ventilation, 1% for hospitalisation, 1 day for duration of hospitalisation, and 2% for all adverse effects.",
      "reason": "Thresholds for interpreting effect sizes (minimally important differences) are reported along with their rationale (chosen by consensus in the absence of quantitative patient values data)."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "we performed the analyses using ratio of means and corresponding 95% CI before calculating the mean difference in days... To facilitate interpretation of results of dichotomous outcomes, we calculated absolute effects per 1000 patients.",
      "reason": "Re-expression of results is described: ratio of means converted to mean difference in days, and relative effects converted to absolute effects per 1000 patients using specified baseline risks."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "we used the mean difference and corresponding 95% CI because we expect similar durations across randomised trials",
      "reason": "A justification is given for the mean difference for duration of hospital stay, but no justification is provided for the other effect measure choices (odds ratios, risk difference, ratio of means)."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "We meta-analysed interventions with ≥100 patients randomised or ≥20 events per treatment arm.",
      "reason": "The manuscript partially describes processes deciding which studies were eligible for each synthesis: it specifies a minimum evidence threshold for meta-analysing interventions (text_6: '≥100 patients randomised or ≥20 events per treatment arm') and states that network meta-analysis was performed 'for outcomes with sufficient data' with pairwise meta-analysis otherwise (text_20). However, it does not explicitly describe processes such as tabulating study intervention characteristics and comparing them against planned synthesis groups (e.g., grouping of antibody/cellular therapy classes), so the description is incomplete."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_13b",
